    if(recovery!=null)signals.push({label:'Recovery',value:`${Math.round(recovery)}% from recorded sleep, energy and soreness`});else signals.push({label:'Recovery',value:'Unavailable — no complete recovery inputs'});
    const pc=ctx?.preSessionContext||{};if(pc.stress!=null&&Number(pc.stress)>0){signals.push({label:'Pre-session stress',value:`${pc.stress}/5`});if(Number(pc.stress)>=4){actions.push('Stress is elevated: extend the warm-up and reassess effort before increasing intensity.');if(!['recovery','completed'].includes(kind)){action='Start conservatively and reassess stress during the warm-up';kind='caution'}}}if(pc.fuelStatus&&pc.fuelStatus!=='unknown')signals.push({label:'Self-reported fuel',value:pc.fuelStatus});if(pc.hydration&&pc.hydration!=='unknown')signals.push({label:'Hydration',value:pc.hydration});if(pc.lastMeal&&pc.lastMeal!=='unknown')signals.push({label:'Last meal',value:pc.lastMeal});if(pc.availableMinutes!=null){signals.push({label:'Time available',value:`${pc.availableMinutes} min`});if(training.duration>Number(pc.availableMinutes))actions.push(`The estimated session duration is about ${training.duration} min, above your ${pc.availableMinutes} min window. Prioritise the main work and trim accessories.`)}if(pc.intensity!=null){signals.push({label:'Planned intensity',value:`${pc.intensity}/5`});if(Number(pc.intensity)>=5&&recovery!=null&&recovery<70)actions.push('Your planned intensity is very high relative to recorded recovery. Consider lowering the target and reassessing after warm-up.')}if(pc.volumePercent!=null){signals.push({label:'Planned volume',value:`${pc.volumePercent}%`});if(Number(pc.volumePercent)<90)actions.push(`You selected ${pc.volumePercent}% volume. Keep that reduction intentional and focus on quality execution.`)}if(pc.fuelStatus==='low')actions.push('You reported low fuel: consider a tolerable carbohydrate source and avoid forcing high intensity if you feel under-fuelled.');if(pc.hydration==='low')actions.push('You reported low hydration: drink fluids and reassess how you feel before training.');if(pc.goal&&pc.goal!=='unknown')signals.push({label:'Session focus',value:pc.goal});
